use std::{collections::HashMap, env, fs};
#[derive(Default,Debug,PartialEq)] struct Summary { info:usize, warn:usize, error:usize, other:usize, messages:HashMap<String,usize> }
fn summarize(input:&str)->Summary { let mut s=Summary::default(); for line in input.lines(){let upper=line.to_ascii_uppercase(); if let Some(pos)=upper.find("ERROR"){s.error+=1;let msg=line[pos+"ERROR".len()..].trim().to_string();*s.messages.entry(msg).or_insert(0)+=1;} else if upper.contains("WARN"){s.warn+=1;} else if upper.contains("INFO"){s.info+=1;} else{s.other+=1;} } s }
fn main(){let path=env::args().nth(1).unwrap_or_else(||{eprintln!("Usage: log-summary FILE");std::process::exit(2)});let data=fs::read_to_string(path).unwrap_or_else(|e|{eprintln!("Could not read file: {e}");std::process::exit(2)});let s=summarize(&data);println!("INFO={} WARN={} ERROR={} OTHER={}",s.info,s.warn,s.error,s.other);let mut common:Vec<_>=s.messages.into_iter().collect();common.sort_by(|a,b|b.1.cmp(&a.1).then_with(||a.0.cmp(&b.0)));for (message,count) in common.into_iter().take(5){println!("{count}x {message}");}}
#[cfg(test)] mod tests {use super::*;#[test]fn counts_levels(){let s=summarize("INFO started\nWARN slow\nERROR disk\n???");assert_eq!((s.info,s.warn,s.error,s.other),(1,1,1,1));}#[test]fn groups_same_error(){let s=summarize("ERROR timeout\nERROR timeout");assert_eq!(s.messages.get("timeout"),Some(&2));}#[test]fn groups_mixed_case_error_messages(){let s=summarize("error disk full\nError disk full");assert_eq!(s.messages.get("disk full"),Some(&2));}}
